const TZ = 'YOUR_CLINIC_TIMEZONE';

const clients      = $('Get All Clients').all().map(i => i.json);
const appointments = $('Get All Appointments').all().map(i => i.json);
const now          = new Date();
const nowIso       = now.toISOString();

// Time windows
const days7ago  = new Date(now); days7ago.setDate(days7ago.getDate() - 7);
const days14ago = new Date(now); days14ago.setDate(days14ago.getDate() - 14);
const days60ago = new Date(now); days60ago.setDate(days60ago.getDate() - 60);
const days90ago = new Date(now); days90ago.setDate(days90ago.getDate() - 90);

const weekLabel = days7ago.toLocaleDateString('en-US', { timeZone: TZ, month: 'short', day: 'numeric' })
  + ' – ' + now.toLocaleDateString('en-US', { timeZone: TZ, month: 'short', day: 'numeric', year: 'numeric' });

// --- LAST WEEK APPOINTMENTS ---
const lastWeekAppts = appointments.filter(a => {
  const d = a['Appointment Date'] ? new Date(a['Appointment Date']) : null;
  return d && !isNaN(d) && d >= days7ago && d <= now;
});
const prevWeekAppts = appointments.filter(a => {
  const d = a['Appointment Date'] ? new Date(a['Appointment Date']) : null;
  return d && !isNaN(d) && d >= days14ago && d < days7ago;
});

const completed    = lastWeekAppts.filter(a => a['Status'] === 'Completed');
const noShows      = lastWeekAppts.filter(a => a['Status'] === 'No-Show');
const prevCompleted = prevWeekAppts.filter(a => a['Status'] === 'Completed');

const revenue      = completed.reduce((s, a) => s + (parseFloat(a['Revenue']) || 0), 0);
const prevRevenue  = prevCompleted.reduce((s, a) => s + (parseFloat(a['Revenue']) || 0), 0);
const noShowRate   = lastWeekAppts.length > 0 ? Math.round(noShows.length / lastWeekAppts.length * 100) : 0;

// Revenue trend arrow
const revTrend = revenue >= prevRevenue
  ? `<span style="color:#059669">▲ ${revenue >= prevRevenue ? '+' : ''}${prevRevenue > 0 ? Math.round((revenue - prevRevenue)/prevRevenue*100) : '—'}% vs last week</span>`
  : `<span style="color:#ef4444">▼ ${Math.round((revenue - prevRevenue)/prevRevenue*100)}% vs last week</span>`;

// --- NEW CLIENTS THIS WEEK ---
const newClients = clients.filter(c => {
  const d = c['Created Date'] ? new Date(c['Created Date']) : null;
  return d && !isNaN(d) && d >= days7ago;
});

// --- ACTIVE CLIENTS TOTAL ---
const activeClients = clients.filter(c => ['Booked','Completed','VIP'].includes(c['Status'])).length;
const vipClients    = clients.filter(c => c['VIP Status'] === 'VIP').length;

// --- AT-RISK (60–90 days) ---
const atRisk = clients.filter(c => {
  if (!c['Last Visit Date'] || (c['Opted Out']||'').toLowerCase() === 'yes') return false;
  const lv = new Date(c['Last Visit Date']);
  if (isNaN(lv)) return false;
  return lv <= days60ago && lv > days90ago && c['Status'] !== 'Lapsed' && c['Status'] !== 'New Inquiry';
});

// --- LAPSED (90+ days) ---
const lapsed = clients.filter(c => {
  if (!c['Last Visit Date'] || (c['Opted Out']||'').toLowerCase() === 'yes') return false;
  const lv = new Date(c['Last Visit Date']);
  if (isNaN(lv)) return false;
  return (lv <= days90ago || c['Status'] === 'Lapsed') && c['Status'] !== 'New Inquiry';
});

// --- REVIEWS THIS WEEK ---
const reviewsRequested = clients.filter(c => {
  // Clients who had review requested recently (approximation from Review Requested = Yes)
  return c['Review Requested'] === 'Yes';
}).length;
const reviewsLeft = clients.filter(c => c['Review Left'] === 'Yes').length;
const reviewRate  = reviewsRequested > 0 ? Math.round(reviewsLeft / reviewsRequested * 100) : 0;

// --- PENDING INQUIRIES (New Inquiry, never booked) ---
const pendingInquiries = clients.filter(c => c['Status'] === 'New Inquiry').length;

// --- NO-SHOW NAMES ---
const noShowRows = noShows.map(a =>
  `<tr style="background:#fff5f5;"><td style="padding:8px 12px;">${a['Client Name']||'—'}</td><td style="padding:8px 12px;">${a['Service']||'—'}</td><td style="padding:8px 12px;">${a['Appointment Date']||'—'}</td><td style="padding:8px 12px;color:#ef4444;">${(a['Post-Appt Follow-Up Sent']||'').toLowerCase()==='yes'?'✅ Sent':'⚠️ Pending'}</td></tr>`
).join('');

// --- AT-RISK NAMES ---
const atRiskRows = atRisk.slice(0, 8).map(c => {
  const d = new Date(c['Last Visit Date']);
  const days = Math.floor((now - d) / 86400000);
  return `<tr><td style="padding:8px 12px;">${c['Client Name']||'—'}</td><td style="padding:8px 12px;">${c['Service Interest']||'—'}</td><td style="padding:8px 12px;"><strong style="color:#f97316">${days}d ago</strong></td></tr>`;
}).join('');
const atRiskMore = atRisk.length > 8 ? `<tr><td colspan="3" style="padding:8px 12px;color:#6b7280;font-style:italic;">+${atRisk.length - 8} more — check dashboard</td></tr>` : '';

return [{
  json: {
    nowIso,
    weekLabel,
    completedCount:    completed.length,
    noShowCount:       noShows.length,
    noShowRate,
    revenueFormatted:  '$' + revenue.toLocaleString('en-US', { maximumFractionDigits: 0 }),
    revTrend,
    newClientsCount:   newClients.length,
    activeClients,
    vipClients,
    pendingInquiries,
    atRiskCount:       atRisk.length,
    lapsedCount:       lapsed.length,
    reviewsRequested,
    reviewsLeft,
    reviewRate,
    noShowRows:        noShowRows || '<tr><td colspan="4" style="padding:12px;color:#059669;text-align:center;">✅ Zero no-shows this week</td></tr>',
    atRiskRows:        (atRiskRows + atRiskMore) || '<tr><td colspan="3" style="padding:12px;color:#059669;text-align:center;">✅ No clients due for re-booking</td></tr>'
  }
}];
